import heapq

def match(orders):
    buy_heap = []   # max-heap by price (store -price), then seq, id
    sell_heap = []  # min-heap by price, then seq, id
    book = {}       # id -> dict with side, price, qty, seq, active
    seq_counter = 0
    trades = []

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq_counter += 1
        remaining = qty
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq_counter, 'active': True}

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                p, s, oid2 = top
            else:
                negp, s, oid2 = top
                p = -negp

            resting = book.get(oid2)
            if resting is None or not resting['active'] or resting['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if typ != 'market':
                if side == 'buy' and p > price:
                    break
                if side == 'sell' and p < price:
                    break

            trade_qty = min(remaining, resting['qty'])

            if side == 'buy':
                trades.append([oid, oid2, p, trade_qty])
            else:
                trades.append([oid2, oid, p, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty
            book[oid]['qty'] = remaining

            if resting['qty'] == 0:
                resting['active'] = False
                heapq.heappop(opp_heap)

            if remaining == 0:
                break

        book[oid]['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            book[oid]['active'] = True
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
        else:
            book[oid]['active'] = False

    return trades

